import{_ as e,o as a,c as t,a as d}from"./app.83c7065c.js";const r="/assets/web-debugging.9a8da7b8.png",m=JSON.parse('{"title":"移动端网页调试技巧","description":"","frontmatter":{"title":"移动端网页调试技巧","date":"2019-09-08"},"headers":[],"relativePath":"2019/mobile-web-debugging-tips.md","lastUpdated":1786184870000}'),i={name:"2019/mobile-web-debugging-tips.md"},h=d('<h3 id="写在前面" tabindex="-1">写在前面 <a class="header-anchor" href="#写在前面" aria-hidden="true">#</a></h3><p>这是4个月前的一篇工作记录，是上一篇Charles使用的扩展版。</p><p>因为平时用Mac，所以只列出了Mac调试不同移动端的情况，windows没有涉及。</p><p>在Mac下调试App常用3种手段：</p><ol><li>USB调试</li><li>使用腾讯开源的vConsole</li><li>使用Charles调试</li></ol><h3 id="usb调试" tabindex="-1">USB调试 <a class="header-anchor" href="#usb调试" aria-hidden="true">#</a></h3><h4 id="ios-usb调试" tabindex="-1">iOS USB调试 <a class="header-anchor" href="#ios-usb调试" aria-hidden="true">#</a></h4><p>功能强大，可以修改网页元素，但有限制挺多的：</p><ol><li>只能在Mac系统调试移动端，windows的开发环境就不行了</li><li>要么调试浏览器打开的网页，要么是Xcode编译运行中的App内页，非编译版的App内页无法调试</li></ol><p>如果以上条件满足的话，那么可以按以下步骤开启调试：</p><ol><li>USB连接手机，手机弹出的对话框选择信任当前电脑</li><li>在Mac上打开Safari，找到 <code>Develop(或“开发”)-&gt;your iphone（即用户给手机取的名字）</code>，就能看到当前可调试的网页，任选一个打开就能在Safari中调试当前网页</li></ol><p>可以直接修改/插入DOM元素，也可以改样式，和直接调试网页一摸一样，所见即得，简直可以说是为所欲为</p><h4 id="android-usb调试" tabindex="-1">Android USB调试 <a class="header-anchor" href="#android-usb调试" aria-hidden="true">#</a></h4><p>Android调试也有一些限制条件：</p><ol><li>Android版本在4.4以上，手机要打开USB调试模式，电脑端必须使用chrome浏览器</li><li>要么调试手机端浏览器打开的网页，要么调试开启了webview调试模式的App内页（WebView.setWebContentsDebuggingEnabled设为true，也就是测试版的App）</li></ol><p>可以按以下步骤开启调试：</p><ol><li>手机切换为开发者模式（不同手机开启方式差异太大，不细说了）</li><li>按照此链接内容完成后续配置：<a href="https://developers.google.com/web/tools/chrome-devtools/remote-debugging/" target="_blank" rel="noreferrer">google官方文档: remote debugging</a></li></ol><p>之后就可以打开浏览器愉快的调试了，happy debugging~</p><h4 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-hidden="true">#</a></h4><table><thead><tr><th>平台</th><th>要求</th><th>适用情景</th><th>是否需要修改代码</th></tr></thead><tbody><tr><td>iOS</td><td>只能在MacOS桌面端调试</td><td>Safari网页<br>Xcode编译运行的App内页，不可用于真机App内页</td><td>否</td></tr><tr><td>Android</td><td>Android 4.4以上<br>手机打开USB调试模式<br>使用Chrome浏览器调试</td><td>Chrome网页<br>测试版App内页（WebView.setWebContentsDebuggingEnabled设为true）</td><td>否</td></tr></tbody></table><h4 id="" tabindex="-1"><a class="header-anchor" href="#" aria-hidden="true">#</a></h4><h3 id="vconsole调试" tabindex="-1">vConsole调试 <a class="header-anchor" href="#vconsole调试" aria-hidden="true">#</a></h3><p>vConsole是腾讯开源调试工具，使用需要修改代码，有一定的侵入性。但是这个代价换来了所有平台的调试能力，在上面2种USB调试条件不满足的情况下，还是很值得使用的。</p><p>事实上，因为大多数情况并不需要USB调试那种修改DOM的能力，目前我在需要调试App内页的时候，用的最多的就是vConsole。查看内嵌页的console输出和api接口返回都很省事，而且通过后端渲染也能控制只在测试环境使用vConsole，对线上环境没有任何影响。</p><p>多数情况下，我觉得它是首要的调试手段。</p><h4 id="小结-1" tabindex="-1">小结 <a class="header-anchor" href="#小结-1" aria-hidden="true">#</a></h4><table><thead><tr><th>平台</th><th>要求</th><th>适用情景</th><th>是否需要修改代码</th></tr></thead><tbody><tr><td>iOS</td><td>无</td><td>各种浏览器网页<br>App内页</td><td>是</td></tr><tr><td>Android</td><td>无</td><td>各种浏览器网页<br>App内页</td><td>是</td></tr></tbody></table><h3 id="-1" tabindex="-1"><a class="header-anchor" href="#-1" aria-hidden="true">#</a></h3><h3 id="charles调试" tabindex="-1">Charles调试 <a class="header-anchor" href="#charles调试" aria-hidden="true">#</a></h3><p>前一篇谈到了：<a href="https://javahashbrown.github.io/Blog/%E4%BD%BF%E7%94%A8Charles%E6%8A%93%E5%8C%85%E7%A7%BB%E5%8A%A8%E7%AB%AF%E7%BD%91%E7%BB%9C%E8%AF%B7%E6%B1%82/" target="_blank" rel="noreferrer">使用Charles抓包移动端网络请求</a></p><p>接口请求、文件下载请求都可以通过抓包查看，但Charles能做的还不止于此。</p><p>打开Charles-&gt;Tools，如下图，红框中的3个工具算是Charles的高级功能了</p><p><img src="'+r+'" alt=""></p><h4 id="map-local-映射到本地文件" tabindex="-1">Map Local - 映射到本地文件 <a class="header-anchor" href="#map-local-映射到本地文件" aria-hidden="true">#</a></h4><p>可以配置代理，将特定链接的访问指向本地文件（夹），将本地文件转发回移动端</p><p>使用场景：</p><ol><li>mock接口返回数据：把按照协议规定的数据保存为json文件，在请求接口地址时，返回这个json文件，就可以当作接口的数据返回</li><li>替换文件，查看模拟展示效果：比如某个页面开发完成但还没有发布，又想看线上的数据展示效果，就可以把对那个页面的请求重定向会本地修改完毕的文件，这样就可以实现用线上数据加载未发布的文件的效果</li></ol><h4 id="rewrite-改写接口返回数据" tabindex="-1">Rewrite - 改写接口返回数据 <a class="header-anchor" href="#rewrite-改写接口返回数据" aria-hidden="true">#</a></h4><p>配置代理，可以针对特定的接口修改其返回数据，可以修改返回数据本身、cookie、请求头等等</p><p>使用场景：mock接口</p><h4 id="map-remote-映射到远程代理" tabindex="-1">Map Remote - 映射到远程代理 <a class="header-anchor" href="#map-remote-映射到远程代理" aria-hidden="true">#</a></h4><p>其实就是重定向，通过配置代理，将对指定URL的请求重定向到配置的另一个远程地址</p><p>使用场景：这个功能没用过，感觉如果用起来和map local的第二种场景差不多</p><h4 id="小结-2" tabindex="-1">小结 <a class="header-anchor" href="#小结-2" aria-hidden="true">#</a></h4><table><thead><tr><th>调试功能</th><th>使用场景</th></tr></thead><tbody><tr><td>映射到本地文件</td><td>mock接口<br>替换文件，查看模拟展示效果</td></tr><tr><td>改写接口返回数据</td><td>mock接口</td></tr><tr><td>映射到远程代理</td><td>替换文件，查看模拟展示效果</td></tr></tbody></table>',45),o=[h];function l(n,s,p,c,b,g){return a(),t("div",null,o)}const _=e(i,[["render",l]]);export{m as __pageData,_ as default};
